css:
.tip-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin: 20px 0 40px;
}
.tip-card {
  background: #fff;
  padding: 20px;
  border-radius: 8px;
  border: 1px solid #d1d5db;
  box-shadow: 0 8px 16px rgba(0,0,0,0.06);
}
.tip-card h3 { margin: 0 0 10px; font-size: 1.05rem; color: #1e293b; }
.tip-card p { color: #475569; font-size: 0.9rem; line-height: 1.6; margin: 0 0 8px; }
.tip-card pre { background: #1e293b; color: #f8fafc; padding: 10px 12px; border-radius: 6px; font-size: 0.8rem; overflow-x: auto; }
@media (max-width: 768px) {
  .tip-cards { grid-template-columns: 1fr; }
}
